<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Product Inventory Manager</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f7fb;color:#17243a}.card{border:0;box-shadow:0 12px 35px #192b4510;border-radius:1rem}.table thead th{white-space:nowrap}.total{font-size:1.15rem;font-weight:700}.brand{letter-spacing:.08em;text-transform:uppercase;color:#526780;font-size:.8rem}</style></head><body><main class="container py-5"><div class="row justify-content-center"><div class="col-lg-10"><div class="mb-4"><div class="brand mb-2">Product Inventory Manager · Jose Perez</div><h1 class="h2 fw-bold">Product inventory</h1><p class="text-secondary">Capture products, track stock value, and update entries in place.</p></div><div class="card p-4 p-md-5 mb-4"><h2 class="h5 mb-4">Add a product</h2><form id="product-form" data-url="{{ route('products.store') }}"><div class="row g-3 align-items-end"><div class="col-md-5"><label for="name" class="form-label">Product name</label><input class="form-control" id="name" name="name" maxlength="120" required></div><div class="col-md-3"><label for="quantity" class="form-label">Quantity in stock</label><input class="form-control" id="quantity" name="quantity" type="number" min="0" step="1" required></div><div class="col-md-2"><label for="price" class="form-label">Price per item</label><input class="form-control" id="price" name="price" inputmode="decimal" placeholder="0.00" required></div><div class="col-md-2 d-grid"><button class="btn btn-primary" id="submit-button">Submit</button></div></div></form><div id="message" class="mt-3" role="status" aria-live="polite"></div></div><div class="card p-3 p-md-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Submitted products</h2><span class="text-secondary small" id="record-count"></span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product name</th><th>Quantity in stock</th><th>Price per item</th><th>Datetime submitted</th><th>Total value</th><th>Action</th></tr></thead><tbody id="products-body"></tbody><tfoot><tr><th colspan="4" class="text-end">Grand total</th><th class="total" id="grand-total">$0.00</th><th></th></tr></tfoot></table></div></div></div></div></main><script>
const initial=@json($products), csrf=document.querySelector('meta[name="csrf-token"]').content, form=document.querySelector('#product-form'), body=document.querySelector('#products-body'); let products=initial;
const money=n=>'$'+Number(n).toFixed(2), esc=s=>{const d=document.createElement('div');d.textContent=s;return d.innerHTML};
function render(){body.innerHTML='';let sum=0;products.sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at)); for(const p of products){const total=Number(p.quantity)*Math.round(Number(p.price)*100)/100;sum+=total;const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(p.name)}</td><td>${p.quantity}</td><td>${money(p.price)}</td><td>${new Date(p.submitted_at).toLocaleString()}</td><td>${money(total)}</td><td><button class="btn btn-sm btn-outline-primary" data-edit="${p.id}">Edit</button></td>`;body.append(tr)} if(!products.length)body.innerHTML='<tr><td colspan="6" class="text-center text-secondary py-4">No products have been submitted yet.</td></tr>'; document.querySelector('#grand-total').textContent=money(sum);document.querySelector('#record-count').textContent=`${products.length} ${products.length===1?'product':'products'}`;}
function message(text,type='success'){const el=document.querySelector('#message');el.className='mt-3 alert alert-'+type;el.textContent=text}
async function send(url,method,data){const r=await fetch(url,{method,headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw j;return j}
form.addEventListener('submit',async e=>{e.preventDefault();const b=document.querySelector('#submit-button');b.disabled=true;b.textContent='Saving…';try{const j=await send(form.dataset.url,'POST',Object.fromEntries(new FormData(form)));products.push(j.product);render();form.reset();message(j.message)}catch(e){message(e.errors?Object.values(e.errors).flat().join(' '):(e.message||'Request failed. Please retry.'),'danger')}finally{b.disabled=false;b.textContent='Submit'}});
body.addEventListener('click',async e=>{const btn=e.target.closest('[data-edit]');if(!btn)return;const p=products.find(x=>x.id===btn.dataset.edit);const name=prompt('Product name',p.name);if(name===null)return;const quantity=prompt('Quantity in stock',p.quantity);if(quantity===null)return;const price=prompt('Price per item',p.price);if(price===null)return;btn.disabled=true;try{const j=await send('/products/'+encodeURIComponent(p.id),'PUT',{name,quantity,price});products=products.map(x=>x.id===p.id?j.product:x);render();message(j.message)}catch(e){message(e.errors?Object.values(e.errors).flat().join(' '):(e.message||'Update failed.'),'danger')}finally{btn.disabled=false}});render();
</script></body></html>
